/* @origin Qian-Ning/LX-Music-Source/LX-Music-Source-main/幻音音源.js */
/*!
 * @name 幻音音源
 * @description 使用TuneHub API的音源
 * @version 1.1
 * @author 竹佀
 */
const { EVENT_NAMES, on, send } = globalThis.lx

// 音频API处理
const getAudioUrl = (source, musicInfo, quality = '128k') => {
    // 源映射
    const sourceMap = {
        'tx': 'qq',
        'kw': 'kuwo', 
        'wy': 'netease'
    }
    
    const platform = sourceMap[source] || 'qq'
    const songmid = musicInfo.songmid || musicInfo.id || musicInfo.mid
    
    if (!songmid) {
        throw new Error('找不到歌曲ID')
    }
    
    // 确保音质参数正确
    // TuneHub API需要完整的音质名称
    const qualityMap = {
        '128k': '128k',
        '320k': '320k',
        'flac': 'flac',
        'flac24bit': 'flac24bit'
    }
    
    const br = qualityMap[quality] || '128k'
    
    // 直接返回TuneHub API链接
    return `https://music-dl.sayqz.com/api/?source=${platform}&id=${songmid}&type=url&br=${br}`
}

// 事件处理
on(EVENT_NAMES.request, ({ source, action, info }) => {
    if (action !== 'musicUrl') {
        return Promise.reject(new Error('仅支持musicUrl操作'))
    }
    
    try {
        const quality = info.type || '128k'
        const url = getAudioUrl(source, info.musicInfo, quality)
        
        console.log(`[TuneHub] 返回链接: ${url}`)
        
        // 关键：直接返回字符串URL，不是对象
        return Promise.resolve(url)
        
    } catch (error) {
        console.error(`[TuneHub] 错误: ${error.message}`)
        return Promise.reject(new Error(`[TuneHub] ${error.message}`))
    }
})

// 初始化
send(EVENT_NAMES.inited, {
    openDevTools: false,
    sources: {
        tx: {
            name: 'QQ音乐 - TuneHub',
            type: 'music',
            actions: ['musicUrl'],
            qualitys: ['128k', '320k', 'flac', 'flac24bit']
        },
        kw: {
            name: '酷我音乐 - TuneHub',
            type: 'music',
            actions: ['musicUrl'],
            qualitys: ['128k', '320k', 'flac', 'flac24bit']
        },
        wy: {
            name: '网易云音乐 - TuneHub',
            type: 'music',
            actions: ['musicUrl'],
            qualitys: ['128k', '320k', 'flac', 'flac24bit']
        }
    }
})

console.log('[TuneHub] 音源初始化完成')

/* @origin Qian-Ning/LX-Music-Source/LX-Music-Source-main/汽水VIP_KMusic音源.js */
// ==UserScript==
// @name        汽水VIP (歌一刀)
// @description 基于第三方接口的汽水音乐音源适配，用于 歌一刀 (LX-style).
// @version     0.1.0
// @author      歌一刀
// ==/UserScript==

(function () {
  const SOURCE_ID = 'qsvip';
  const SOURCE_NAME = '汽水VIP';

  const API_BASE = 'http://api.vsaa.cn/api/music.qishui.vip';
  const PROXY_SERVER = 'https://proxy.qishui.vsaa.cn/qishui/proxy';

  function buildQuery(params) {
    // JSCore on iOS may not have URLSearchParams; build query manually.
    const p = params || {};
    const keys = Object.keys(p);
    if (!keys.length) return '';
    const parts = [];
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const v = p[k];
      if (v === undefined || v === null) continue;
      parts.push(encodeURIComponent(String(k)) + '=' + encodeURIComponent(String(v)));
    }
    return parts.length ? ('?' + parts.join('&')) : '';
  }

  function requestValues(url, options) {
    return new Promise((resolve, reject) => {
      try {
        lx.request(url, options || { method: 'GET' }, (err, resp) => {
          if (err) reject(err);
          else resolve(resp || {});
        });
      } catch (e) {
        reject(e && e.message ? e.message : String(e));
      }
    });
  }

  async function getJSON(url, params, timeoutMs) {
    const full = `${url}${buildQuery(params)}`;
    const resp = await requestValues(full, { method: 'GET', timeout: timeoutMs || 15000 });
    return resp && resp.body ? resp.body : null;
  }

  async function postJSON(url, body, timeoutMs) {
    const resp = await requestValues(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: body || {},
      timeout: timeoutMs || 60000,
    });
    return resp && resp.body ? resp.body : null;
  }

  function pickId(musicInfo) {
    if (!musicInfo) return '';
    return (
      musicInfo.id ||
      musicInfo.songmid ||
      musicInfo.songId ||
      musicInfo.hash ||
      musicInfo.rid ||
      musicInfo.mid ||
      musicInfo.strMediaMid ||
      musicInfo.mediaId ||
      ''
    ).toString();
  }

  function mapQuality(type) {
    // KMusic quality types -> api.vsaa.cn expected levels (best-effort)
    switch ((type || '').toLowerCase()) {
      case '128k':
        return 'low';
      case '320k':
        return 'standard';
      case 'flac':
        return 'lossless';
      case 'flac24bit':
        return 'hi_res';
      default:
        return 'standard';
    }
  }

  function normalizeSongItem(item) {
    // Fields consumed by KMusic JSEngine.searchSongs mapping:
    // name/singer/albumName + id-like fields.
    const id = (item && (item.id || item.vid)) ? String(item.id || item.vid) : '';
    return {
      id,
      songmid: id,
      hash: id,
      name: (item && item.name) ? String(item.name) : '未知歌曲',
      singer: (item && item.artists) ? String(item.artists) : '未知歌手',
      albumName: (item && item.album) ? String(item.album) : '',
      // duration in seconds (KMusic expects seconds)
      duration: item && item.duration ? Math.floor(Number(item.duration) / 1000) : 0,
      // Keep raw fields for potential future UI.
      pic: item && (item.cover || item.pic) ? String(item.cover || item.pic) : '',
      _raw: item || {},
    };
  }

  // Register as an LX-style source
  lx.send('inited', {
    sources: {
      [SOURCE_ID]: {
        name: SOURCE_NAME,
        type: 'music',
        actions: ['musicSearch', 'musicUrl', 'lyric'],
        qualitys: [
          { type: '128k', desc: '标准' },
          { type: '320k', desc: '高音质' },
          { type: 'flac', desc: '无损' },
          { type: 'flac24bit', desc: 'Hi-Res' },
        ],
      },
    },
  });

  lx.on('request', async ({ action, source, info }) => {
    if (source !== SOURCE_ID) return;

    if (action === 'musicSearch' || action === 'search') {
      const keyword = (info && info.keyword) ? String(info.keyword) : '';
      const page = (info && info.page) ? Number(info.page) : 1;
      const limit = (info && info.limit) ? Number(info.limit) : 30;
      if (!keyword) return { isEnd: true, list: [] };

      const res = await getJSON(API_BASE, {
        act: 'search',
        keywords: keyword,
        page,
        pagesize: limit,
        type: 'music',
      }, 15000);

      const lists = (res && res.data && Array.isArray(res.data.lists)) ? res.data.lists : [];
      const total = (res && res.data && res.data.total) ? Number(res.data.total) : lists.length;
      const isEnd = lists.length < limit;
      return { isEnd, list: lists.map(normalizeSongItem), total };
    }

    if (action === 'musicUrl') {
      const q = mapQuality(info && info.type);
      const musicInfo = (info && info.musicInfo) || {};
      const id = pickId(musicInfo);
      if (!id) return '';

      const res = await getJSON(API_BASE, { act: 'song', id, quality: q }, 20000);
      const song = (res && Array.isArray(res.data)) ? res.data[0] : (res && res.data && res.data[0]) ? res.data[0] : null;
      if (!song || !song.url) return '';

      // Some responses require decryption via proxy server.
      if (song.ekey) {
        const ext = song.codec_type ? String(song.codec_type) : 'aac';
        const proxy = await postJSON(PROXY_SERVER, {
          url: song.url,
          key: song.ekey,
          filename: song.name || 'KMusic',
          ext,
        }, 60000);
        if (proxy && Number(proxy.code) === 200 && proxy.url) {
          return String(proxy.url);
        }
        // If proxy fails, surface an empty result so the app can auto-switch sources.
        return '';
      }

      return String(song.url);
    }

    if (action === 'lyric') {
      const musicInfo = (info && info.musicInfo) || {};
      const id = pickId(musicInfo);
      if (!id) return { lyric: '' };
      const res = await getJSON(API_BASE, { act: 'song', id }, 15000);
      const song = (res && Array.isArray(res.data)) ? res.data[0] : (res && res.data && res.data[0]) ? res.data[0] : null;
      const lyric = song && song.lyric ? String(song.lyric) : '';
      return { lyric };
    }
  });
})();

/* @origin Qian-Ning/LX-Music-Source/LX-Music-Source-main/聚合Hi-Res音乐音源v1.0.js */
/*!
 * @name 聚合Hi-Res音乐音源v1.0
 * @description 整合长青/W/星海音源，支持网易云/QQ/酷狗/酷我/咪咕 Hi-Res 24bit
 * @version v1.0
 * @updateUrl https://zrcdy.dpdns.org/lx/xinghai-music-source.js
 * @support 网易云/QQ/酷狗/酷我/咪咕（24bit/FLAC/320k等全音质）
 */
// ============================ 核心配置（整合多源）============================
const CONFIG = {
  // 版本更新配置
  update: {
    versionApiUrl: 'https://zrcdy.dpdns.org/lx/version.php',
    latestScriptUrl: 'https://zrcdy.dpdns.org/lx/xinghai-music-source.js',
    currentVersion: 'v1.0'
  },
  // 核心解析API（聚合多源接口）
  api: {
    main: 'https://music-api.gdstudio.xyz/api.php?use_xbridge3=true&loader_name=forest&need_sec_link=1&sec_link_scene=im&theme=light',
    backup: 'https://13413.kstore.vip/lxmusic/changqing.json'
  },
  // 频率限制（防请求超限）
  rateLimit: {
    maxRequests: 60,
    timeWindow: 5 * 60 * 1000 // 60次/5分钟
  },
  // 音质支持配置（Hi-Res 24bit优先）
  quality: {
    wy: ['flac24bit', 'flac', '320k', '192k', '128k'], // 网易云
    tx: ['flac24bit', 'flac', '320k', '192k', '128k'], // QQ音乐
    kg: ['flac24bit', 'flac', '320k', '192k', '128k'], // 酷狗
    kw: ['flac24bit', 'flac', '320k', '192k', '128k'], // 酷我
    mg: ['flac', '320k', '192k', '128k'] // 咪咕（原生无24bit）
  },
  // 平台映射（对接解析API）
  sourceMap: { wy: 'netease', tx: 'tencent', kg: 'kugou', kw: 'kuwo', mg: 'migu' },
  // 音质码映射（对接API参数）
  qualityMap: { '128k': '128', '192k': '192', '320k': '320', 'flac': '740', 'flac24bit': '999' }
};

// 全局对象获取（适配LX Music系列播放器）
const { EVENT_NAMES, request, on, send } = globalThis.lx || globalThis['lx'];
const MUSIC_PLATFORMS = Object.keys(CONFIG.quality);

// ============================ 工具函数（通用/稳定）============================
/**
 * 日志简化输出
 */
const log = (action, source, msg, status = 'info') => {
  console.log(`[聚合音源-${action}] [${source}] [${status}] ${msg}`);
};

/**
 * 音质自动适配/降级（24bit不可用则降级到FLAC，依次类推）
 */
const mapQuality = (target, source) => {
  const available = CONFIG.quality[source];
  if (available.includes(target)) return target;
  // 按优先级匹配（从高到低）
  const priority = [...available];
  for (const q of priority) {
    if (available.includes(q)) return q;
  }
  return '128k'; // 保底音质
};

/**
 * 请求频率限制器（防止接口封禁）
 */
class RateLimiter {
  constructor() {
    this.requests = [];
  }
  check() {
    const now = Date.now();
    this.requests = this.requests.filter(t => now - t < CONFIG.rateLimit.timeWindow);
    const allowed = this.requests.length < CONFIG.rateLimit.maxRequests;
    allowed && this.requests.push(now);
    return {
      allowed,
      resetIn: Math.ceil((Math.min(...this.requests) + CONFIG.rateLimit.timeWindow - now) / 60000) || 5
    };
  }
}
const rateLimiter = new RateLimiter();

/**
 * 封装HTTP请求（适配播放器request API，带错误处理）
 */
const httpRequest = (url, options = { method: 'GET' }) => {
  return new Promise((resolve, reject) => {
    const cancel = request(url, { timeout: 15000, ...options }, (err, resp) => {
      if (err) return reject(new Error(`网络错误：${err.message}`));
      let body = resp.body;
      // 自动解析JSON
      if (typeof body === 'string' && (body.startsWith('{') || body.startsWith('['))) {
        try { body = JSON.parse(body); } catch (e) {}
      }
      resolve({ body, status: resp.statusCode, headers: resp.headers || {} });
    });
  });
};

/**
 * 版本比对（检查更新）
 */
const compareVersions = (remote, current) => {
  const r = remote.replace(/^v/, '').split('.').map(Number);
  const c = current.replace(/^v/, '').split('.').map(Number);
  for (let i = 0; i < Math.max(r.length, c.length); i++) {
    if ((r[i] || 0) > (c[i] || 0)) return true;
  }
  return false;
};

// ============================ 核心功能（多源整合）============================
/**
 * 检查版本更新（整合星海更新逻辑）
 */
const checkUpdate = async () => {
  try {
    const resp = await httpRequest(CONFIG.update.versionApiUrl);
    if (resp.status !== 200) throw new Error('更新接口无响应');
    const remoteVer = resp.body.version || resp.body.VERSION || '';
    if (!remoteVer) return;
    if (compareVersions(remoteVer, CONFIG.update.currentVersion)) {
      const logMsg = `发现新版本：${remoteVer}（当前：${CONFIG.update.currentVersion}）`;
      send(EVENT_NAMES.updateAlert, {
        log: `【聚合Hi-Res音源更新】\n${logMsg}\n更新地址：${CONFIG.update.latestScriptUrl}`,
        updateUrl: CONFIG.update.latestScriptUrl,
        confirmText: '立即更新',
        cancelText: '暂不更新'
      });
      log('update', 'system', logMsg, 'warn');
    }
  } catch (err) {
    log('update', 'system', `检查更新失败：${err.message}`, 'error');
  }
};

/**
 * 获取音乐播放地址（核心解析，整合长青/W/星海逻辑）
 * @param {string} source 平台（wy/tx/kg/kw/mg）
 * @param {object} musicInfo 歌曲信息（id/hash/songmid）
 * @param {string} targetQuality 目标音质
 */
const getMusicUrl = async (source, musicInfo, targetQuality) => {
  // 1. 频率限制检查
  const limit = rateLimiter.check();
  if (!limit.allowed) {
    throw new Error(`请求超限，请${limit.resetIn}分钟后重试（${CONFIG.rateLimit.maxRequests}次/5分钟）`);
  }

  // 2. 验证歌曲ID和平台
  const songId = musicInfo.hash ?? musicInfo.songmid ?? musicInfo.id ?? '';
  if (!songId || !MUSIC_PLATFORMS.includes(source)) {
    throw new Error('无效歌曲ID/不支持的平台');
  }

  // 3. 音质适配
  const actualQuality = mapQuality(targetQuality, source);
  const apiSource = CONFIG.sourceMap[source];
  const apiQuality = CONFIG.qualityMap[actualQuality];
  if (!apiSource || !apiQuality) {
    throw new Error(`平台${source}不支持${actualQuality}音质`);
  }
  log('resolve', source, `音质适配：${targetQuality} -> ${actualQuality}`, 'info');

  // 4. 拼接解析接口（主接口优先，失败自动切备用）
  const requestUrl = `${CONFIG.api.main}&types=url&source=${apiSource}&id=${songId}&br=${apiQuality}`;
  try {
    // 5. 发起请求并解析结果
    const resp = await httpRequest(requestUrl, {
      headers: { 'User-Agent': 'LX-Music-Mobile', 'Accept': 'application/json' }
    });
    if (!resp.body || !resp.body.url) {
      throw new Error(resp.body.msg || '接口无有效播放地址');
    }
    log('resolve', source, `解析成功（${actualQuality}）：${musicInfo.name || '未知歌曲'}`, 'success');
    return resp.body.url;
  } catch (err) {
    // 备用接口兜底（长青音源）
    log('resolve', source, `主接口失败：${err.message}，尝试备用接口`, 'warn');
    const backupResp = await httpRequest(CONFIG.api.backup);
    if (!backupResp.body) throw new Error('备用接口也失败，请稍后重试');
    return backupResp.body.url || '';
  }
};

// ============================ 播放器注册（核心入口）============================
/**
 * 注册音乐平台配置（供播放器识别）
 */
const registerSources = () => {
  const musicSources = {};
  MUSIC_PLATFORMS.forEach(source => {
    musicSources[source] = {
      name: { wy: '网易云音乐', tx: 'QQ音乐', kg: '酷狗音乐', kw: '酷我音乐', mg: '咪咕音乐' }[source],
      type: 'music',
      actions: ['musicUrl'],
      qualitys: CONFIG.quality[source]
    };
  });
  // 通知播放器初始化完成
  send(EVENT_NAMES.inited, {
    status: true,
    openDevTools: false,
    sources: musicSources
  });
  log('init', 'system', '多源聚合音源初始化完成，支持Hi-Res 24bit', 'success');
};

/**
 * 注册播放器事件监听（响应播放地址请求）
 */
const registerEvents = () => {
  on(EVENT_NAMES.request, async ({ action, source, info }) => {
    if (action !== 'musicUrl' || !info?.musicInfo || !info?.type) {
      return Promise.reject(new Error('无效请求参数'));
    }
    try {
      const url = await getMusicUrl(source, info.musicInfo, info.type);
      return Promise.resolve(url);
    } catch (err) {
      log('request', source, err.message, 'error');
      return Promise.reject(new Error(err.message));
    }
  });
};

// ============================ 初始化执行 =============================
(async () => {
  registerSources(); // 注册平台
  registerEvents();  // 注册事件
  setTimeout(checkUpdate, 2000); // 延迟检查更新，不阻塞初始化
})();

/* @origin TianpingHsu/lx-music-source/lx-music-source-master/ikun-source.js */
/*!
 * @name ikun公益音源
 * @description Telegram:@ikun0014，QQ:607047319
 * @version v103
 * @author 不知名纯鹿人
 * @repository https://github.com/lxmusics/lx-music-api-server
 */

// 是否开启开发模式
const DEV_ENABLE = false
// 服务端地址
const API_URL = "https://lxmusic.ikunshare.com:9763"
// 服务端配置的请求key
const API_KEY = `ikunsource`
// 音质配置(key为音源名称,不要乱填.如果你账号为VIP可以填写到hires)
// 全部的支持值: ['128k', '320k', 'flac', 'flac24bit']
const MUSIC_QUALITY = JSON.parse('{"kw":["128k","320k","flac","flac24bit"],"kg":["128k","320k","flac","flac24bit"],"tx":["128k","320k","flac","flac24bit"],"wy":["128k","320k","flac","flac24bit"],"mg":["128k","320k","flac","flac24bit"]}')
// 音源配置(默认为自动生成,可以修改为手动)
const MUSIC_SOURCE = Object.keys(MUSIC_QUALITY)
MUSIC_SOURCE.push('local')

/**
 * 下面的东西就不要修改了
 */
const { EVENT_NAMES, request, on, send, utils, env, version } = globalThis.lx

/**
 * URL请求
 *
 * @param {string} url - 请求的地址
 * @param {object} options - 请求的配置文件
 * @return {Promise} 携带响应体的Promise对象
 */
const httpFetch = (url, options = { method: 'GET' }) => {
  return new Promise((resolve, reject) => {
    console.log('--- start --- ' + url)
    request(url, options, (err, resp) => {
      if (err) return reject(err)
      console.log('API Response: ', resp)
      resolve(resp)
    })
  })
}

/**
 * Encodes the given data to base64.
 *
 * @param {type} data - the data to be encoded
 * @return {string} the base64 encoded string
 */
const handleBase64Encode = (data) => {
  var data = utils.buffer.from(data, 'utf-8')
  return utils.buffer.bufToString(data, 'base64')
}

/**
 * 
 * @param {string} source - 音源
 * @param {object} musicInfo - 歌曲信息
 * @param {string} quality - 音质
 * @returns {Promise<string>} 歌曲播放链接
 * @throws {Error} - 错误消息
 */
const handleGetMusicUrl = async (source, musicInfo, quality) => {
  if (source == 'local') {
    if (!musicInfo.songmid.startsWith('server_')) throw new Error('upsupported local file')
    const songId = musicInfo.songmid
    const requestBody = {
      p: songId.replace('server_', ''),
    }
    var t = 'c'
    var b = handleBase64Encode(JSON.stringify(requestBody)) /* url safe*/.replace(/\+/g, '-').replace(/\//g, '_')
    const targetUrl = `${API_URL}/local/${t}?q=${b}`
    const request = await httpFetch(targetUrl, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': `${env ? `lx-music-${env}/${version}` : `lx-music-request/${version}`}`,
        'X-Request-Key': API_KEY,
      },
      follow_max: 5,
    })
    const { body } = request
    if (body.code == 0 && body.data && body.data.file) {
      var t = 'u'
      var b = handleBase64Encode(JSON.stringify(requestBody)) /* url safe*/.replace(/\+/g, '-').replace(/\//g, '_')
      return `${API_URL}/local/${t}?q=${b}`
    }
    throw new Error('404 Not Found')
  }

  const songId = musicInfo.hash ?? musicInfo.songmid

  const request = await httpFetch(`${API_URL}/url/${source}/${songId}/${quality}`, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': `${env ? `lx-music-${env}/${version}` : `lx-music-request/${version}`}`,
      'X-Request-Key': API_KEY,
    },
    follow_max: 5,
  })
  const { body } = request

  if (!body || isNaN(Number(body.code))) throw new Error('unknow error')
  if (env != 'mobile') console.groupEnd()
  switch (body.code) {
